import java.awt.*;
import javax.swing.*;
public class BorderDemo {
  public static void main(String[] args) {
    JFrame f = new JFrame("BorderLayout");
    f.setLayout(new BorderLayout());
    f.add(new JButton("东"), BorderLayout.EAST);
    f.add(new JButton("南"), BorderLayout.SOUTH);
    f.add(new JButton("西"), BorderLayout.WEST);
    f.add(new JButton("北"), BorderLayout.NORTH);
    f.add(new JButton("中"), BorderLayout.CENTER);
    f.setSize(300, 200);
    f.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
    f.setVisible(true);
  }
}

import java.awt.*;
import java.awt.event.*;
import javax.swing.*;
public class ClickCount extends JFrame implements ActionListener {
  JButton btn = new JButton("计数");
  JLabel label = new JLabel("0");
  int count = 0;
  ClickCount() {
    super("计数器");
    setLayout(new FlowLayout());
    add(btn);
    add(label);
    btn.addActionListener(this);
    setSize(250, 100);
    setDefaultCloseOperation(EXIT_ON_CLOSE);
    setVisible(true);
  }
  public void actionPerformed(ActionEvent e) {
    count++;
    label.setText(String.valueOf(count));
  }
  public static void main(String[] args) {
    new ClickCount();
  }
}
